from itertools import product
import heapq


def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        blocked = set(data.get("blocked", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        n = len(jobs)
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            selected = [jobs[i] for i in range(n) if mask >> i & 1]
            ids = {job["id"] for job in selected}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = {}
            for job in selected:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in selected:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            feasible = True
            for _, delta in sorted(events):  # end events precede start events at ties
                active += delta
                if active > capacity:
                    feasible = False
                    break
            if not feasible:
                continue
            value = sum(job["value"] for job in selected)
            names = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                (value == best_value and
                 ((tie == "smallest" and names < best_ids) or
                  (tie == "largest" and names > best_ids)))):
                best_value, best_ids = value, names
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (seq, event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)
        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {}
        for name in names:
            rows[name] = {row["version"]: row for row in packages[name]}
        choices = []
        for name in names:
            available = [-1]
            for version in rows[name]:
                if version in blocked.get(name, []):
                    continue
                if name in pins and pins[name] != version:
                    continue
                available.append(version)
            choices.append(available)

        best_vector = None
        best_versions = None
        for vector in product(*choices):
            versions = {name: version for name, version in zip(names, vector)
                        if version != -1}
            if any(name not in versions or not low <= versions[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            edges = {name: [] for name in versions}
            valid = True
            for name, version in versions.items():
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in versions or not dep["min"] <= versions[other] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue
            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                if any(not visit(other) for other in edges[name]):
                    return False
                state[name] = 2
                return True
            if any(not visit(name) for name in edges):
                continue
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(versions):
                continue
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        start = data["start"]
        initial_mask = bit_for.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | bit_for.get(nxt, 0)
                    next_state = (nxt, next_mask, left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_mask, left))
        return {"arrival": None}
    return solve


